mapper.select:
SELECT P.prdt_cd, P.coal_co_cd, C.code_nm AS coal_co_nm, P.rep_prdt_cd, R.rep_prdt_nm, P.prdt_nm, P.prdt_desc, P.sale_start_date, P.sale_end_date, P.use_yn, P.created_id, P.created_at, P.updated_id, P.updated_at FROM tb_product P LEFT OUTER JOIN tb_rep_prdt R ON P.rep_prdt_cd = R.rep_prdt_cd LEFT OUTER JOIN tb_code C ON P.coal_co_cd = C.code_cd AND C.code_group_cd = 'INS_COMPANY'
AND C.code_group_cd = 'INS_COMPANY_TYPE' AND C.code_cd = #{insType}
AND P.coal_co_cd = #{companyCd}
AND P.prdt_nm LIKE CONCAT('%', #{prdtNm}, '%')
AND P.sale_end_date >= #{startDate}
AND P.sale_start_date <= #{endDate}
ORDER BY P.created_at DESC

mapper.update:
UPDATE tb_product
coal_co_cd = #{coalCoCd}, rep_prdt_cd = #{repPrdtCd}, prdt_nm = #{prdtNm}, prdt_desc = #{prdtDesc}, sale_start_date = #{saleStartDate}, sale_end_date = #{saleEndDate}, use_yn = #{useYn}, updated_id = 'admin_sys', updated_at = NOW()
WHERE prdt_cd = #{prdtCd}
